// remocn components as registry entries (ids "remocn.<name>"), built from runtime/remocn/catalog.json
// (generated by scripts/remocn-manifest.ts from components/remocn).
import type { ComponentMeta } from "../registry";
import type { Category } from "../types";
import catalog from "./catalog.json";
import { REMOCN_PREFIX, isRemocnId } from "./types";

interface CatalogEntry {
  id: string;
  category: "text" | "background" | "decor" | "scene";
  title: string;
  description: string;
  mood: string[];
  dependencies: string[];
  /** has image props the user's uploaded pictures can fill */
  media?: boolean;
}

export { REMOCN_PREFIX, isRemocnId };

const MOODS: ComponentMeta["mood"] = ["calm", "energetic", "playful", "elegant", "techy", "bold"];

export const REMOCN_COMPONENTS: ComponentMeta[] = (catalog as CatalogEntry[]).map((e) => ({
  id: REMOCN_PREFIX + e.id,
  framework: "remocn",
  category: e.category as Category,
  name: e.title,
  description: e.description,
  uses: ["<Player>", ...e.dependencies.filter((d) => d !== "remotion")],
  mood: e.mood.filter((m): m is ComponentMeta["mood"][number] => (MOODS as string[]).includes(m)),
  ...(e.media ? { media: true } : {}),
}));

/** true when the component can show the user's uploaded image(s) */
export const remocnAcceptsMedia = (id: string | undefined) => !!id && !!REMOCN_COMPONENTS.find((c) => c.id === id)?.media;

const STOP = new Set(["the", "and", "for", "with", "that", "this", "from", "your", "you", "our", "are", "slide", "video", "make", "use", "show", "about", "into", "effect", "animation", "animated", "remocn", "component", "please", "want", "like", "more", "less"]);
const words = (t: string) => (t.toLowerCase().match(/[a-z0-9]+/g) ?? []).filter((w) => w.length > 2 && !STOP.has(w));

/** deterministic rng (mulberry32) */
function rng(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * A short, relevant list of remocn components of one category for a slide — the designer can't take all ~870 in
 * its prompt, so it gets the best keyword matches for the request/slide text (+ mood), topped up with mood picks.
 */
export function remocnCandidates(opts: { category: Category; query: string; mood?: string; limit?: number; seed?: number; avoid?: string[]; media?: boolean }): ComponentMeta[] {
  const limit = opts.limit ?? 5;
  const q = words(opts.query);
  const r = rng(opts.seed ?? 1);
  // media: only components that can show the user's uploaded image
  const pool = REMOCN_COMPONENTS.filter((c) => c.category === opts.category && !opts.avoid?.includes(c.id) && (!opts.media || c.media));
  const scored = pool.map((c) => {
    const name = `${c.id} ${c.name}`.toLowerCase();
    const hay = `${name} ${c.description}`.toLowerCase();
    let score = 0;
    for (const w of q) {
      const stem = w.replace(/(ing|ed|es|s)$/, "");
      if (name.includes(w) || (stem.length > 2 && name.includes(stem))) score += 3;
      else if (hay.includes(w) || (stem.length > 2 && hay.includes(stem))) score += 1;
    }
    if (opts.mood && (c.mood as string[]).includes(opts.mood)) score += 0.5;
    return { c, score, tie: r() };
  });
  scored.sort((a, b) => b.score - a.score || a.tie - b.tie);
  return scored.slice(0, limit).map((s) => s.c);
}
